private static final class ClientChunkStatusView implements ChunkLoadStatusView {
   private final int radius;
   @Nullable
   private ClientLevel level;
   @Nullable
   private LocalPlayer player;
   private int centerX;
   private int centerZ;

   ClientChunkStatusView(final int radius) {
      this.radius = radius;
   }

   void bind(final ClientLevel level, final LocalPlayer player) {
      this.level = level;
      this.player = player;
      this.followPlayer();
   }

   void followPlayer() {
      if (this.player != null) {
         ChunkPos pos = this.player.chunkPosition();
         this.centerX = pos.x();
         this.centerZ = pos.z();
      }
   }

