      @Override
      public ChunkStatus get(final int x, final int z) {
         if (this.level == null) {
            return ChunkStatus.EMPTY;
         }
         LevelChunk chunk = this.level.getChunkSource().getChunk(x + this.centerX - this.radius, z + this.centerZ - this.radius, ChunkStatus.FULL, false);
         return chunk != null ? ChunkStatus.FULL : ChunkStatus.EMPTY;
      }

      @Override
      public int radius() {
         return this.radius;
      }
   }
